{
  "name": "pi-cua",
  "version": "0.1.0",
  "description": "Keep pi local. Run workspace tools on your computers with Cua Spaces.",
  "files": [
    "index.ts",
    "remote.ts",
    "spaces.ts",
    "tools.ts",
    "windows.ts",
    "workspace.ts",
    "git-transfer.cjs",
    "assets/"
  ],
  "type": "module",
  "keywords": [
    "pi-package",
    "pi-extension",
    "cua",
    "spaces"
  ],
  "author": "Zane Chee",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/injaneity/pi-cua.git"
  },
  "homepage": "https://github.com/injaneity/pi-cua#readme",
  "bugs": {
    "url": "https://github.com/injaneity/pi-cua/issues"
  },
  "pi": {
    "extensions": [
      "./index.ts"
    ]
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "@earendil-works/pi-tui": "*",
    "typebox": "*"
  },
  "scripts": {
    "test": "node --experimental-transform-types --no-warnings --test test/*.test.ts test/*.test.mjs"
  },
  "dependencies": {
    "@trycua/cua": "^0.5.0"
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "1.3.0",
    "@earendil-works/pi-tui": "1.3.0",
    "typebox": "*"
  }
}
